using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// SPARC v8 转译器
    /// SPARC: 寄存器窗口机制，32个全局寄存器 + 8-32个窗口寄存器
    /// 虚拟寄存器映射：R0-R7 → %g0-%g7（全局寄存器）
    ///                 R8-R15 → %o0-%o7（输出寄存器）
    ///                 R16-R23 → %l0-%l7（本地寄存器）
    ///                 R24-R31 → %i0-%i7（输入寄存器）
    /// </summary>
    public class TranslatorSPARC : Translator32bit
    {
        public override string ARCH_NAME => "SPARC";

        // SPARC 中断上下文 (寄存器窗口机制，save/restore 处理大部分上下文)
        protected override string[] ContextRegNames() => new[] { "%g1","%g2","%g3","%g4","%g5","%g6","%g7" };
        protected override string NativeInt(int vector) => "ta 0";
        protected override string NativeIret() => "rett";
        protected override string NativeCli() => "";
        protected override string NativeSti() => "";
        protected override void EmitSaveContext()
        {
            Emit("        save %sp, -96, %sp");
            int off = 68;
            foreach (var r in ContextRegNames())
            {
                Emit($"        st {r}, [%sp+{off}]");
                off += 4;
            }
        }
        protected override void EmitRestoreContext()
        {
            int off = 68;
            foreach (var r in ContextRegNames())
            {
                Emit($"        ld [%sp+{off}], {r}");
                off += 4;
            }
            Emit("        restore");
        }

        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "%g0" }, { 1, "%g1" }, { 2, "%g2" }, { 3, "%g3" },
            { 4, "%g4" }, { 5, "%g5" }, { 6, "%g6" }, { 7, "%g7" },
            { 8, "%o0" }, { 9, "%o1" }, { 10, "%o2" }, { 11, "%o3" },
            { 12, "%o4" }, { 13, "%o5" }, { 14, "%sp" }, { 15, "%o7" },
            { 16, "%l0" }, { 17, "%l1" }, { 18, "%l2" }, { 19, "%l3" },
            { 20, "%l4" }, { 21, "%l5" }, { 22, "%l6" }, { 23, "%l7" },
            { 24, "%i0" }, { 25, "%i1" }, { 26, "%i2" }, { 27, "%i3" },
            { 28, "%i4" }, { 29, "%i5" }, { 30, "%fp" }, { 31, "%i7" }
        };

        private readonly string[] CC_NAMES = { "eq", "ne", "le", "ge", "lt", "gt", "cc", "cs" };

        public TranslatorSPARC(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("! SPARC v8 Assembly - Translated from VML");
            Emit("! Generated by VML Translator");
            Emit("! Assembler: sparc-as (binutils)");
            Emit("");
            Emit("        .seg \"text\"");
            Emit("        .global main");
            Emit("        .align 4");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("");
                Emit("        .seg \"data\"");
                Emit("        .align 8");
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is string strValue)
                    {
                        Emit($"        .global {name}");
                        Emit($"{name}:");
                        Emit($"        .asciz  \"{strValue}\"");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        Emit($"        .global {name}");
                        Emit($"{name}:");
                        foreach (var item in listValue)
                        {
                            if (int.TryParse(item.ToString(), out int intValue))
                                Emit($"        .word   {intValue}");
                        }
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"        .global {name}");
                        Emit($"{name}:");
                        Emit($"        .word   {intValue}");
                    }
                }
                Emit("");
            }
        }

        protected override void EmitCode()
        {
            Emit("        .seg \"text\"");
            Emit("        .align 4");
            Emit("");

            foreach (var instr in VmlProgram.Instructions)
            {
                if (!string.IsNullOrEmpty(instr.Label))
                {
                    Emit($"{instr.Label}:");
                }
                NormalizeAndTranslate(instr);
            }
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MUL:
                    TranslateMul(instr);
                    break;
                case OpCode.DIV:
                    TranslateDiv(instr);
                    break;
                case OpCode.MOD:
                    // SPARC: sdiv 商→dst, 余数→%y; rd %y 读取余数
                    Emit($"        sdiv {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, %g1");
                    Emit($"        rd %y, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.TEST:
                    // SPARC: andcc 设置标志位但不存储结果
                    Emit($"        andcc {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, %g0");
                    break;
                case OpCode.AND:
                    Emit($"        and {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.OR:
                    Emit($"        or {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.XOR:
                    Emit($"        xor {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.NOT:
                    Emit($"        not {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.SHL:
                    Emit($"        sll {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.SHR:
                    Emit($"        srl {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.INC:
                    Emit($"        inc {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.DEC:
                    Emit($"        dec {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.NEG:
                    Emit($"        neg {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.JMP:
                    Emit($"        ba {instr.Operands[0].Value}");
                    Emit("        nop");
                    break;
                case OpCode.JZ:
                case OpCode.JE:
                    Emit($"        be {instr.Operands[0].Value}");
                    Emit("        nop");
                    break;
                case OpCode.JNZ:
                case OpCode.JNE:
                    Emit($"        bne {instr.Operands[0].Value}");
                    Emit("        nop");
                    break;
                case OpCode.JL:
                    Emit($"        bl {instr.Operands[0].Value}");
                    Emit("        nop");
                    break;
                case OpCode.JLE:
                    Emit($"        ble {instr.Operands[0].Value}");
                    Emit("        nop");
                    break;
                case OpCode.JG:
                    Emit($"        bg {instr.Operands[0].Value}");
                    Emit("        nop");
                    break;
                case OpCode.JGE:
                    Emit($"        bge {instr.Operands[0].Value}");
                    Emit("        nop");
                    break;
                case OpCode.HALT:
                    Emit("        ta 0");
                    Emit("        nop");
                    break;
                case OpCode.NOP:
                    Emit("        nop");
                    break;
                case OpCode.STI:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit("        ta 0");
                    Emit("        nop");
                    break;
                case OpCode.CATCH:
                    Emit("        ; CATCH - 设置陷阱向量");
                    break;
                case OpCode.ENDCATCH:
                    break;
                case OpCode.PUSH:
                    Emit($"        st {GetOperandValue(instr.Operands[0])}, [%sp - 4]");
                    Emit("        sub %sp, 4, %sp");
                    break;
                case OpCode.POP:
                    Emit("        add %sp, 4, %sp");
                    Emit("        ld [%sp - 4], %l0");
                    break;
                case OpCode.CALL:
                    Emit($"        call {instr.Operands[0].Value}");
                    Emit("        nop");
                    break;
                case OpCode.RET:
                    Emit("        retl");
                    Emit("        nop");
                    break;
                // case OpCode.RET_VAL:
                //     Emit($"        mov {GetOperandValue(instr.Operands[0])}, %o0");
                //     Emit("        retl");
                //     Emit("        nop");
                //     break;
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;
                case OpCode.SYSCALL:
                    Emit($"        mov {GetOperandValue(instr.Operands[0])}, %g1");
                    Emit("        ta 0");
                    Emit("        nop");
                    break;
                // ── 浮点 / 64-bit 指令 ──
                // SPARC v8 使用软件库函数模拟浮点和 64-bit 运算
                case OpCode.FADD:
                case OpCode.FSUB:
                case OpCode.FMUL:
                case OpCode.FDIV:
                case OpCode.FNEG:
                case OpCode.FCMP:
                case OpCode.I2F:
                case OpCode.F2I:
                case OpCode.F2D:
                case OpCode.D2F:
                case OpCode.MOVEF:
                case OpCode.MOVED:
                case OpCode.MOVEL:
                case OpCode.FPUSH:
                case OpCode.FPOP:
                case OpCode.DPUSH:
                case OpCode.DPOP:
                case OpCode.DADD:
                case OpCode.DSUB:
                case OpCode.DMUL:
                case OpCode.DDIV:
                case OpCode.DNEG:
                case OpCode.DCMP:
                case OpCode.ADDL:
                case OpCode.SUBL:
                case OpCode.MULL:
                case OpCode.DIVL:
                case OpCode.MODL:
                case OpCode.NEGL:
                case OpCode.CMPL:
                case OpCode.I2L:
                case OpCode.L2I:
                case OpCode.F2L:
                case OpCode.L2F:
                case OpCode.D2L:
                case OpCode.L2D:
                    Emit($"        call __{instr.Opcode.ToString().ToLower()}");
                    Emit("        nop");
                    break;
                case OpCode.MOVEB:
                    Emit($"        and {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, 0xFF");
                    break;
                case OpCode.MOVEH:
                    Emit($"        and {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, 0xFFFF");
                    break;
                case OpCode.PUSHB:
                case OpCode.PUSHH:
                    Emit("        sub %sp, %sp, 4");
                    Emit($"        st {GetOperandValue(instr.Operands[0])}, [%sp]");
                    break;
                case OpCode.POPB:
                    Emit($"        ld {GetOperandValue(instr.Operands[0])}, [%sp]");
                    Emit("        add %sp, %sp, 4");
                    Emit($"        and {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 0xFF");
                    break;
                case OpCode.POPH:
                    Emit($"        ld {GetOperandValue(instr.Operands[0])}, [%sp]");
                    Emit("        add %sp, %sp, 4");
                    Emit($"        and {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 0xFFFF");
                    break;
                case OpCode.ENTER:
                    Emit("        save %sp, -96, %sp");
                    Emit($"        sub %sp, {instr.Operands[0].Value}, %sp");
                    break;
                case OpCode.LEAVE:
                    Emit("        restore");
                    Emit("        retl");
                    Emit("        nop");
                    break;                                case OpCode.SHLV:
                    Emit($"        sll {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[2])}, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.SHRV:
                    Emit($"        srl {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[2])}, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.ZERO:
                    Emit($"        clr {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.BREAK:
                    Emit("        ta 1");
                    break;
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.CLC:
                    Emit("        ; CLC — SPARC has no carry flag");
                    break;
                case OpCode.STC:
                    Emit("        ; STC — SPARC has no carry flag");
                    break;
                case OpCode.CLI:
                    Emit("        ; CLI — disable interrupts not implemented");
                    break;
                case OpCode.INT:
                    Emit("        ; INT — software interrupt not implemented");
                    break;
                case OpCode.IRET:
                    Emit("        ; IRET — interrupt return not implemented");
                    break;
                case OpCode.PUSHL:
                case OpCode.POPL:
                case OpCode.I2D:
                case OpCode.D2I:
                // 符号扩展/条件移动/循环移位 (v1.66.28+)
                case OpCode.SEXTB: case OpCode.SEXTH:
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"        call __{instr.Opcode.ToString().ToLower()}");
                    Emit("        nop");
                    break;
                default:
                    Emit($"        ! UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src);
                Emit($"        set {value}, {GetOperandValue(dst)}");
            }
            else if (src.Type == OperandType.MEMORY)
            {
                Emit($"        ld [{src.Value}], {GetOperandValue(dst)}");
            }
            else if (src.Type == OperandType.REGISTER)
            {
                Emit($"        mov {GetOperandValue(src)}, {GetOperandValue(dst)}");
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.REGISTER)
            {
                if (dst.Type == OperandType.MEMORY)
                {
                    Emit($"        st {GetOperandValue(src)}, [{dst.Value}]");
                }
                else if (dst.Type == OperandType.REGISTER)
                {
                    Emit($"        mov {GetOperandValue(src)}, {GetOperandValue(dst)}");
                }
            }
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"        add {GetOperandValue(src1)}, {src2.Value}, {GetOperandValue(dst)}");
            }
            else
            {
                Emit($"        add {GetOperandValue(src1)}, {GetOperandValue(src2)}, {GetOperandValue(dst)}");
            }
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"        sub {GetOperandValue(src1)}, {src2.Value}, {GetOperandValue(dst)}");
            }
            else
            {
                Emit($"        sub {GetOperandValue(src1)}, {GetOperandValue(src2)}, {GetOperandValue(dst)}");
            }
        }

        private void TranslateMul(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];
            Emit($"        smul {GetOperandValue(src1)}, {GetOperandValue(src2)}, {GetOperandValue(dst)}");
        }

        private void TranslateDiv(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];
            Emit($"        sdiv {GetOperandValue(src1)}, {GetOperandValue(src2)}, {GetOperandValue(dst)}");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];
            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"        subcc {GetOperandValue(src1)}, {src2.Value}, %g0");
            }
            else
            {
                Emit($"        subcc {GetOperandValue(src1)}, {GetOperandValue(src2)}, %g0");
            }
        }

        protected override string MapRegister(int regNum)
        {
            if (regNum < 0) return "%g0";
            if (regNum > 31) return "%i7";
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"%r{regNum}";
        }
    }
}
